import RoundCounter from "./RoundCounter.jsx";
export default function App(){const[rounds,setRounds]=useState(0);return <main className="stack"><h1>Práctica deliberada</h1><RoundCounter value={rounds} onIncrement={()=>setRounds((current)=>current+1)} onDecrement={()=>setRounds((current)=>Math.max(0,current-1))} onReset={()=>setRounds(0)}/></main>}

import { useState } from "react";
import IdeaForm from "./IdeaForm.jsx";import IdeaList from "./IdeaList.jsx";
const initialIdeas=[{id:"i1",text:"Mapa mental"},{id:"i2",text:"Prototipo en papel"}];
export default function App(){const[ideas,setIdeas]=useState(initialIdeas);function addIdea(text){setIdeas((current)=>[...current,{id:crypto.randomUUID(),text}])}function removeIdea(id){setIdeas((current)=>current.filter((idea)=>idea.id!==id))}return <main className="stack"><h1>Banco de ideas</h1><IdeaForm onAdd={addIdea}/><IdeaList ideas={ideas} onRemove={removeIdea}/></main>}

import { useState } from "react";import FilterBar from "./FilterBar.jsx";import TaskList from "./TaskList.jsx";
const initialTasks=[{id:"t1",title:"Leer requisitos",done:true},{id:"t2",title:"Construir interfaz",done:false},{id:"t3",title:"Probar interacciones",done:false}];
export default function App(){const[tasks,setTasks]=useState(initialTasks);const[filter,setFilter]=useState("all");const visibleTasks=tasks.filter((task)=>filter==="pending"?!task.done:filter==="done"?task.done:true);function toggleTask(id){setTasks((current)=>current.map((task)=>task.id===id?{...task,done:!task.done}:task))}return <main className="stack"><h1>Plan de entrega</h1><FilterBar value={filter} onChange={setFilter}/><TaskList tasks={visibleTasks} onToggle={toggleTask}/></main>}

import { useState } from "react";import ProductList from "./ProductList.jsx";import CartSummary from "./CartSummary.jsx";
const products=[{id:"p1",name:"Cuaderno",priceCents:450},{id:"p2",name:"Lápiz",priceCents:120}];
export default function App(){const[cart,setCart]=useState({});function addProduct(id){setCart((current)=>({...current,[id]:(current[id]??0)+1}))}function decreaseProduct(id){setCart((current)=>{const next={...current};if(next[id]<=1)delete next[id];else next[id]-=1;return next})}const items=products.filter((product)=>cart[product.id]).map((product)=>({...product,quantity:cart[product.id]}));const units=items.reduce((total,item)=>total+item.quantity,0);const totalCents=items.reduce((total,item)=>total+item.priceCents*item.quantity,0);return <main className="stack"><h1>Tienda de aula</h1><ProductList products={products} onAdd={addProduct}/><CartSummary items={items} units={units} totalCents={totalCents} onDecrease={decreaseProduct}/></main>}
